import { test } from "@e2e/fixtures";
import * as flows from "@e2e/flows";
import * as ui from "@e2e/ui-actions";

test.describe("Rich messages", () => {
  test.use({
    inspectorOptions: {
      inspectMode: true,
    },
  });

  test("Quick-reply buttons on inspector memory flow are clickable", async ({ inspectorPage }) => {
    await flows.richMessages.triggerMemoryAndButtonsFlow(inspectorPage);

    await test.step("Assert trace-mode quick-reply buttons are clickable", async () => {
      await ui.conversationLog
        .assertions(inspectorPage)
        .userMessageIsVisible("/SetSlots(inspector_trace_mode=Memory)");
    });
  });

  test("Custom payload modal and bot image render after memory flow completes", async ({
    inspectorPage,
  }) => {
    await flows.richMessages.triggerMemoryAndButtonsFlow(inspectorPage, {
      waitForSummary: true,
    });

    await test.step("Open custom JSON modal from bot message", async () => {
      await ui.modal.actions(inspectorPage).openCustomJsonModal();
      await ui.modal.assertions(inspectorPage).customJsonDialogIsVisible();
      await ui.modal.assertions(inspectorPage).customJsonDialogContains("inspector_trace_fixture");
    });

    await test.step("Assert bot message image renders", async () => {
      await ui.conversationLog.assertions(inspectorPage).botImageIsVisible();
    });
  });
});
